/* Lookup table for cang data */
typedef struct {
    const char *path;
    const uint8_t *data;
    size_t size;
} EmbeddedEntry;

static const EmbeddedEntry cang_entries[] = {
    { "data/collision/circle_collision_angles.bin", cang_circle_collision_angles, 1024 },
    { "data/collision/gengar_collision_angles.bin", cang_gengar_collision_angles, 3072 },
    { "data/collision/haunter_collision_angles.bin", cang_haunter_collision_angles, 1280 },
    { "data/collision/meowth_collision_angles.bin", cang_meowth_collision_angles, 1920 },
    { "data/collision/meowth_jewel_collision_angles.bin", cang_meowth_jewel_collision_angles, 576 },
};

#define CANG_COUNT (sizeof(cang_entries) / sizeof(cang_entries[0]))

const uint8_t *embedded_collision_angles(const char *path, size_t *out_size) {
    for (size_t i = 0; i < CANG_COUNT; i++) {
        if (strcmp(path, cang_entries[i].path) == 0) {
            *out_size = cang_entries[i].size;
            return cang_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
